// Autonomously generated by an AI agent: tests of the new replacement front end.
#include "transient_detector.h"

#include <algorithm>
#include <cmath>
#include <functional>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <utility>
#include <vector>

namespace {
void require(bool condition, const std::string& message) {
    if (!condition) throw std::runtime_error(message);
}

std::vector<float> pulses(int rate, std::size_t channels, double frequency = 100,
        bool opposite = false, double origin = 0.2) {
    std::vector<float> audio(static_cast<std::size_t>(3 * rate) * channels);
    for (int beat = 0; beat < 6; ++beat) {
        const auto start = static_cast<std::size_t>(std::llround((origin + beat * 0.5) * rate));
        for (int frame = 0; frame < rate / 40; ++frame) {
            const double time = static_cast<double>(frame) / rate;
            const auto value = static_cast<float>(0.8 * std::exp(-100 * time) *
                    std::cos(2 * std::acos(-1.0) * frequency * time));
            for (std::size_t channel = 0; channel < channels; ++channel) {
                audio[(start + frame) * channels + channel] =
                        opposite && channel == 1 ? -value : value;
            }
        }
    }
    return audio;
}

void check_same(const std::vector<phasegrid::Transient>& first,
        const std::vector<phasegrid::Transient>& second) {
    require(first.size() == second.size(), "different event counts");
    for (std::size_t i = 0; i < first.size(); ++i) {
        require(first[i].time_seconds == second[i].time_seconds, "different event time");
        require(first[i].weight == second[i].weight, "different event weight");
        require(first[i].bass_weight == second[i].bass_weight, "different bass weight");
    }
}

void check_pulses(const std::vector<phasegrid::Transient>& events) {
    require(events.size() == 6, "expected exactly six synthetic onsets");
    for (std::size_t i = 0; i < events.size(); ++i) {
        require(std::abs(events[i].time_seconds - (0.2 + i * 0.5)) < 0.010,
                "onset timing differs by at least 10 ms");
        require(events[i].weight > 0 && std::isfinite(events[i].weight),
                "invalid onset weight");
        require(events[i].bass_weight >= 0 && events[i].bass_weight <= events[i].weight,
                "invalid bass weight");
    }
}
} // namespace

int main() {
    const std::vector<std::pair<const char*, std::function<void()>>> tests{
        {"silence", [] {
            phasegrid::TransientDetector detector;
            std::vector<float> silence(2 * 44100);
            require(detector.process(silence.data(), silence.size()), detector.last_error());
            require(detector.finalize(), detector.last_error());
            require(detector.transients().empty(), "silence produced an onset");
        }},
        {"pulse_times_at_three_rates", [] {
            for (int rate : {8000, 44100, 48000}) {
                phasegrid::TransientDetector::Config config;
                config.sample_rate = rate;
                phasegrid::TransientDetector detector(config);
                const auto audio = pulses(rate, 2);
                require(detector.process(audio.data(), audio.size()), detector.last_error());
                require(detector.finalize(), detector.last_error());
                check_pulses(detector.transients());
            }
        }},
        {"arbitrary_complete_frame_chunks_are_identical", [] {
            const auto audio = pulses(44100, 2);
            phasegrid::TransientDetector whole;
            require(whole.process(audio.data(), audio.size()), whole.last_error());
            require(whole.finalize(), whole.last_error());
            for (std::size_t frames : {1U, 73U, 511U, 4096U}) {
                phasegrid::TransientDetector chunked;
                for (std::size_t start = 0; start < audio.size(); start += frames * 2) {
                    const auto count = std::min(frames * 2, audio.size() - start);
                    require(chunked.process(audio.data() + start, count), chunked.last_error());
                }
                require(chunked.finalize(), chunked.last_error());
                check_same(whole.transients(), chunked.transients());
            }
        }},
        {"timestamp_origin_and_non_aligned_pulses", [] {
            for (double origin : {0.0, 0.0001, 0.0049, 0.10177, 0.1993}) {
                phasegrid::TransientDetector detector;
                const auto audio = pulses(44100, 2, 100, false, origin);
                require(detector.process(audio.data(), audio.size()), detector.last_error());
                require(detector.finalize(), detector.last_error());
                require(detector.transients().size() == 6, "missing arbitrarily aligned pulse");
                for (std::size_t i = 0; i < detector.transients().size(); ++i) {
                    require(std::abs(detector.transients()[i].time_seconds -
                                    (origin + i * 0.5)) < 0.010,
                            "onset estimator has unexpected timing bias");
                }
            }
        }},
        {"refractory_distance_is_respected", [] {
            phasegrid::TransientDetector::Config config;
            config.refractory_seconds = 0.8;
            phasegrid::TransientDetector detector(config);
            const auto audio = pulses(44100, 2);
            require(detector.process(audio.data(), audio.size()), detector.last_error());
            require(detector.finalize(), detector.last_error());
            require(detector.transients().size() >= 2 && detector.transients().size() < 6,
                    "refractory suppression did not affect dense onsets");
            for (std::size_t i = 1; i < detector.transients().size(); ++i) {
                require(detector.transients()[i].time_seconds -
                                detector.transients()[i - 1].time_seconds >= 0.8,
                        "onsets are closer than configured refractory distance");
            }
        }},
        {"mono_and_opposite_polarity_stereo_preserve_onsets", [] {
            phasegrid::TransientDetector::Config config;
            config.channels = 1;
            phasegrid::TransientDetector mono(config);
            phasegrid::TransientDetector stereo;
            const auto mono_audio = pulses(44100, 1);
            const auto stereo_audio = pulses(44100, 2, 100, true);
            require(mono.process(mono_audio.data(), mono_audio.size()), mono.last_error());
            require(stereo.process(stereo_audio.data(), stereo_audio.size()), stereo.last_error());
            require(mono.finalize() && stereo.finalize(), "finalization failed");
            check_same(mono.transients(), stereo.transients());
        }},
        {"bass_weight_distinguishes_low_and_high_attacks", [] {
            phasegrid::TransientDetector low;
            phasegrid::TransientDetector high;
            const auto low_audio = pulses(44100, 2, 100);
            const auto high_audio = pulses(44100, 2, 3000);
            require(low.process(low_audio.data(), low_audio.size()), low.last_error());
            require(high.process(high_audio.data(), high_audio.size()), high.last_error());
            require(low.finalize() && high.finalize(), "finalization failed");
            require(low.transients().size() == 6 && high.transients().size() == 6,
                    "missing low/high onsets");
            const auto& a = low.transients().front();
            const auto& b = high.transients().front();
            require(a.bass_weight / a.weight > 3 * b.bass_weight / b.weight,
                    "bass channel does not distinguish attacks");
        }},
        {"nonfinite_and_partial_frames_reject_without_state_change", [] {
            phasegrid::TransientDetector detector;
            float odd[3]{};
            require(!detector.process(odd, 3), "partial frame accepted");
            require(detector.frames_processed() == 0, "partial frame changed state");
            float bad[]{0, 0, 0, std::numeric_limits<float>::quiet_NaN()};
            require(!detector.process(bad, 4), "NaN accepted");
            require(detector.frames_processed() == 0, "NaN changed state");
            bad[3] = std::numeric_limits<float>::infinity();
            require(!detector.process(bad, 4), "Inf accepted");
            require(detector.frames_processed() == 0, "Inf changed state");
            require(!detector.process(nullptr, 2), "null PCM accepted");
            require(detector.process(nullptr, 0), "empty PCM rejected");
            require(detector.last_error().empty(), "success did not clear old error");
        }},
        {"invalid_configurations_are_rejected", [] {
            phasegrid::TransientDetector detector;
            for (double rate : {0.0, -44100.0, std::numeric_limits<double>::infinity()}) {
                phasegrid::TransientDetector::Config config;
                config.sample_rate = rate;
                require(!detector.reset(config), "invalid sample rate accepted");
                require(!detector.process(nullptr, 0), "invalid detector accepted input");
            }
            phasegrid::TransientDetector::Config config;
            config.channels = 3;
            require(!detector.reset(config), "unsupported channel count accepted");
            config = {};
            config.hop_seconds = 0.1;
            require(!detector.reset(config), "hop greater than window accepted");
        }},
        {"reset_drops_previous_audio_and_events", [] {
            phasegrid::TransientDetector detector;
            const auto audio = pulses(44100, 2);
            require(detector.process(audio.data(), audio.size()), detector.last_error());
            require(detector.finalize(), detector.last_error());
            require(!detector.transients().empty(), "pulse test yielded no events");
            require(detector.reset({}), detector.last_error());
            require(detector.frames_processed() == 0 && detector.transients().empty(),
                    "reset retained previous result");
            std::vector<float> silence(44100 * 2);
            require(detector.process(silence.data(), silence.size()), detector.last_error());
            require(detector.finalize(), detector.last_error());
            require(detector.transients().empty(), "stale onset after reset");
        }},
        {"finalization_is_idempotent_and_blocks_further_input", [] {
            phasegrid::TransientDetector detector;
            const auto audio = pulses(44100, 2);
            require(detector.process(audio.data(), audio.size()), detector.last_error());
            require(detector.finalize(), detector.last_error());
            const auto events = detector.transients();
            require(detector.finalize(), detector.last_error());
            check_same(events, detector.transients());
            require(!detector.process(audio.data(), 2), "input after finalization accepted");
            require(detector.finalize() && detector.last_error().empty(),
                    "idempotent finalization did not clear an old error");
        }},
        {"short_input_and_tail_peak", [] {
            phasegrid::TransientDetector detector;
            std::vector<float> short_input(20, 0.5f);
            require(detector.process(short_input.data(), short_input.size()), detector.last_error());
            require(detector.finalize(), detector.last_error());
            require(detector.transients().empty(), "sub-window signal produced an onset");
            require(detector.reset({}), detector.last_error());
            std::vector<float> tail(44100 * 2, 0);
            for (std::size_t frame = 44040; frame < 44100; ++frame) {
                tail[frame * 2] = tail[frame * 2 + 1] = 0.8f;
            }
            require(detector.process(tail.data(), tail.size()), detector.last_error());
            require(detector.finalize(), detector.last_error());
            require(detector.transients().size() == 1, "final onset was not flushed");
            require(detector.transients().front().time_seconds <= 1,
                    "final onset outside audio duration");
        }},
    };
    int failures = 0;
    for (const auto& test : tests) {
        try {
            test.second();
            std::cout << "PASS " << test.first << '\n';
        } catch (const std::exception& error) {
            ++failures;
            std::cerr << "FAIL " << test.first << ": " << error.what() << '\n';
        }
    }
    std::cout << tests.size() - failures << '/' << tests.size() << " tests passed\n";
    return failures ? 1 : 0;
}
// End of autonomously generated AI-agent front-end tests.
